<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Architex OS — Datum UI Integrated Prototype v7 · Meetings</title>
<link rel="stylesheet" href="/assets/v1-clone/css/reference-shell.css">
<style id="v1-clone-bootstrap-gate">body[data-v1-clone-state="loading"]>*{visibility:hidden}body[data-v1-clone-state="error"] .app{display:none}</style>
</head>
<body data-v1-clone-state="loading">
<div class="app" id="app">
  <aside class="os-rail">
    <div class="brand">
      <button class="logo-btn" onclick="toggleRail()" aria-label="Expand global Architex OS navigation"><img src="data:image/png;base64," alt="Architex origami bird"></button>
      <div class="brand-copy"><b>ARCHITEX OS</b><span>Built environment operating system</span></div>
      <button class="rail-close" onclick="toggleRail()" aria-label="Collapse menu">×</button>
    </div>
    <div class="rail-caption"><b>Global OS layer</b><br>Switches between the Command Centre, project workspaces, standalone tools and platform-wide services. The next panel is contextual.</div>
    <nav class="os-menu" id="globalMenu" aria-label="Global OS navigation"></nav>
    <div class="rail-spacer"></div>
    <div class="rail-user"><div class="avatar">JK</div><div class="user-copy"><b>Justin Kruger</b><span>Architect · Platform owner</span></div></div>
  </aside>
  <aside class="navigator" id="navigator"></aside>
  <header class="topbar">
    <button class="top-btn" onclick="toggleNavigator()" aria-label="Toggle context navigator" id="navToggle"></button>
    <div class="crumb" id="breadcrumb"></div>
    <div class="top-spacer"></div>
    <span class="scope-pill" id="scopePill"></span>
    <div class="project-chip" id="projectChip"></div>
    <button class="top-btn" onclick="openTool('wingman',state.mode)" aria-label="Open Wingman" id="wingmanTop"></button>
    <button class="top-btn" onclick="toggleInspector()" aria-label="Toggle contextual inspector" id="inspectToggle"></button>
  </header>
  <main class="main" id="main"></main>
  <aside class="inspector">
    <div class="inspect-head"><div><h3 id="inspectTitle"></h3><p id="inspectSub"></p></div><button class="inspect-close" onclick="toggleInspector()">×</button></div>
    <div class="inspect-tabs"><button class="inspect-tab active" onclick="setInspector('context',this)">Context</button><button class="inspect-tab" onclick="setInspector('wingman',this)">Wingman</button><button class="inspect-tab" onclick="setInspector('activity',this)">Activity</button></div>
    <div class="inspect-body" id="inspectBody"></div>
  </aside>
</div>

<button class="feedback-fab" id="feedbackFab" type="button" aria-label="Send feedback" title="Send feedback (Ctrl+Shift+F)" onclick="toggleFeedback()"></button>
<section class="feedback-panel" id="feedbackPanel" role="dialog" aria-modal="false" aria-label="Architex feedback loop">
  <div class="feedback-panel-head"><div id="feedbackHeadIcon"></div><div><h3>Send feedback</h3><p>Context is captured automatically.</p></div><button class="feedback-x" onclick="toggleFeedback(false)" aria-label="Close feedback">×</button></div>
  <div class="feedback-panel-body">
    <div class="feedback-context" id="feedbackContext"></div>
    <div class="feedback-tabs"><button class="active" data-feedback-tab="submit" onclick="setFeedbackTab('submit',this)">Submit</button><button data-feedback-tab="mine" onclick="setFeedbackTab('mine',this)">My feedback</button></div>
    <div id="feedbackSubmitView">
      <div class="feedback-categories" id="feedbackCategories"></div>
      <textarea id="feedbackText" maxlength="2000" placeholder="Describe the issue, idea or improvement..." oninput="updateFeedbackCount()"></textarea>
      <div class="feedback-meta"><span>Minimum 10 characters</span><span id="feedbackCount">0 / 2,000</span></div>
      <div class="feedback-attach" onclick="showToast('Attachment capture is represented in this prototype.')">Attach screenshot or supporting file</div>
      <button class="feedback-submit" onclick="submitFeedback()">Submit feedback</button>
    </div>
    <div id="feedbackMineView" style="display:none"><div class="feedback-list" id="feedbackRecords"></div></div>
  </div>
</section>
<div class="feedback-toast" id="feedbackToast"></div>
<script>if(window.matchMedia('(max-width: 1200px)').matches){document.getElementById('app').classList.add('inspector-closed');}if(window.matchMedia('(max-width: 800px)').matches){document.getElementById('app').classList.add('nav-compact');}</script>
